mapper.select:
SELECT id, strategy_id AS strategyId, from_date AS fromDate, to_date AS toDate,
       trade_date AS tradeDate, portfolio_value AS portfolioValue,
       return_pct AS returnPct, cash, equity, created_at AS createdAt
FROM quant_backtest_result
WHERE strategy_id = #{strategyId}
  AND from_date = #{fromDate}
  AND to_date = #{toDate}
ORDER BY trade_date

mapper.delete:
DELETE FROM quant_backtest_result
WHERE strategy_id = #{strategyId}
  AND from_date = #{fromDate}
  AND to_date = #{toDate}

DELETE FROM quant_backtest_result
WHERE from_date <= #{toDate}
  AND to_date >= #{fromDate}
